{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance","requirement":"Rent increases are capped at the lower of 3% per year or 80% of the 12-month change in CPI; no increase if CPI is negative. Owners must give written notice of the ordinance and tenant rights with any rent increase.","key_value":"Lower of 3% per year or 80% of CPI change over most recent 12 months; 0% if CPI negative","coverage_conditions":"Residential rents and mobile home spaces, except residential buildings constructed after February 1, 1995, and mobile home spaces offered for rent after January 1, 1990.","applicability":{"conditions":[{"type":"built","role":"exempt","op":"after","date":"1995-02-01","basis":"construction"}],"per_tenancy":null,"coverage_quotes":["The rent cap does not apply to residential buildings constructed after February 1, 1995, or to mobile home spaces offered for rent after January 1, 1990."]},"exemptions":"Residential buildings constructed after February 1, 1995; mobile home spaces offered for rent after January 1, 1990.","penalty":null,"effective_date":"2021-11-19","valid_through":null,"citation":"Rent Stabilization Ordinance","quoted_span":"Increase in residential rents are limited to the lower of 3% per year, or 80% of the percent change in the Consumer Price Index over the most recent 12-month period. If the CPI is negative, no rent increase is permitted.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana Just Cause Eviction Ordinance","requirement":"After 30 days of tenancy, an owner may not terminate without just cause stated in written notice, must first give the tenant a chance to cure, and for no-fault terminations must provide 3 months' relocation assistance or waive the final 3 months' rent.","key_value":"Just cause after 30 days; 3 months' relocation assistance or 3 months' rent waiver for no-fault","coverage_conditions":"Residential tenancies, except housing produced in the last 15 years, deed-restricted affordable housing, hotel and transient occupancy, hospital and care facilities, dormitories and other shared living quarters.","applicability":{"conditions":[{"type":"built_within_years","role":"exempt","years":15,"basis":"construction"},{"type":"other","text":"deed-restricted affordable housing is exempt"}],"per_tenancy":"Just cause protection applies after 30 days of tenancy; no-fault terminations require 3 months' relocation assistance or a waiver of the final 3 months' rent","coverage_quotes":["The Just Cause Ordinance shall not apply to certain types of residential property, including housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; and other shared living quarters."]},"exemptions":"Housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; other shared living quarters.","penalty":null,"effective_date":"2021-11-19","valid_through":null,"citation":"Just Cause Eviction Ordinance","quoted_span":"After 30 days, an owner shall not terminate a tenancy without just cause, which shall be stated in a written notice.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
